task find_Min_Swaps(arr: seq, n: int) returns (r: int)
  requires n >= 0
  requires len(arr) == n
  ensures r >= 0
  ensures r == count_ones_before_zeros(arr)
{
  r := 0;
  var ones: int := 0;
  var zeros: int := 0;
  var i: int := 0;
  while i < n
    invariant 0 <= i and i <= n
    invariant r == ones * zeros
    invariant ones + zeros == i
    decreases n - i
  {
    if arr[i] == 1 {
      ones := ones + 1;
    } else {
      zeros := zeros + 1;
      r := r + ones;
    }
    i := i + 1;
  }
}
